class Solution {
public:
    int lengthOfLongestSubstring(string s) {
        // last: 字符 -> 最近一次出现的下标（哈希表把重复判断降到 O(1)）
        unordered_map<char, int> last;
        int ans = 0, l = 0;   // l 是窗口左边界
        for (int r = 0; r < (int)s.size(); ++r) {
            char c = s[r];
            // c 上次出现的位置若还在窗口内，左边界必须跳到重复位置之后
            auto it = last.find(c);
            if (it != last.end() && it->second >= l) l = it->second + 1;
            last[c] = r;                 // 记录/更新最近下标
            ans = max(ans, r - l + 1);   // [l, r] 是当前无重复窗口
        }
        return ans;   // 空串时循环不执行，ans 初始 0 天然正确
    }
};

