#include <bits/stdc++.h>
using namespace std;

int main() {
    string s;
    getline(cin, s);   // 整行读取，允许空串
    if (!s.empty() && s.back() == '\r') s.pop_back();   // 兼容 Windows 换行

    // last: 字符 -> 最近一次出现的下标
    unordered_map<char, int> last;
    int ans = 0, l = 0;   // l 是窗口左边界
    for (int r = 0; r < (int)s.size(); ++r) {
        char c = s[r];
        // c 上次出现的位置若还在窗口内，左边界跳到重复位置之后
        auto it = last.find(c);
        if (it != last.end() && it->second >= l) l = it->second + 1;
        last[c] = r;                 // 记录/更新最近下标
        ans = max(ans, r - l + 1);   // [l, r] 是当前无重复窗口
    }
    cout << ans << endl;
    return 0;
}

