class Solution {
    public int lengthOfLongestSubstring(String s) {
        // last: 字符 -> 最近一次出现的下标（哈希表把重复判断降到 O(1)）
        Map<Character, Integer> last = new HashMap<>();
        int ans = 0, l = 0;   // l 是窗口左边界
        for (int r = 0; r < s.length(); r++) {
            char c = s.charAt(r);
            // c 上次出现的位置若还在窗口内，左边界必须跳到重复位置之后
            if (last.containsKey(c) && last.get(c) >= l) {
                l = last.get(c) + 1;
            }
            last.put(c, r);                   // 记录/更新最近下标
            ans = Math.max(ans, r - l + 1);   // [l, r] 是当前无重复窗口
        }
        return ans;   // 空串时循环不执行，ans 初始 0 天然正确
    }
}

