func lengthOfLongestSubstring(s string) int {
	last := map[byte]int{} // 字符 -> 最近一次出现的下标
	ans, l := 0, 0         // l 是窗口左边界
	for r := 0; r < len(s); r++ {
		c := s[r]
		// c 上次出现的位置若还在窗口内，左边界必须跳到重复位置之后
		if idx, ok := last[c]; ok && idx >= l {
			l = idx + 1
		}
		last[c] = r // 记录/更新最近下标
		if cur := r - l + 1; cur > ans { // [l, r] 是当前无重复窗口
			ans = cur
		}
	}
	return ans // 空串时循环不执行，ans 初始 0 天然正确
}
